package net.officefloor.hq.app.sheet;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** A sheet: everything else in the app is kept per sheet. It starts empty when first loaded. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The keys of the settings that carry a figure, each dated. */
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String CAP = "cap";
    public static final String FLOOR = "floor";
    public static final String TERMS = "terms";
    public static final String LATE_PCT = "late-pct";
    public static final String PROOF_THRESHOLD = "proof-threshold";
    public static final String NOTE_THRESHOLD = "note-threshold";
    public static final String GRACE = "grace";

    /** The actions the permission matrix covers, each with the roles that may take it under the standing rule. */
    public static final Map<String, String> STANDING_PERMISSIONS = Map.of(
            "open", "clerk,steward", "settle", "clerk,steward", "void", "clerk,steward",
            "reassign", "steward", "close", "clerk,steward", "reopen", "steward");

    @Id
    private String id;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's today: every date-dependent decision on the sheet uses it, never the clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last claim number the sheet gave out; 0 before any claim is opened. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** The starting clerk limit (before every from-date): a claim a clerk settles whose due is above it goes PENDING for a steward; null for no limit. */
    @Column(name = "clerk_limit")
    private BigDecimal clerkLimit;

    /** The starting cap (before every from-date): a person's due-total is at most it; null for no cap. */
    @Column(name = "cap")
    private BigDecimal cap;

    /** The starting proof threshold (before every from-date): a claim whose due is above it cannot be settled or approved with no proofs; null for none. */
    @Column(name = "proof_threshold")
    private BigDecimal proofThreshold;

    /** The starting floor (before every from-date): a claim's live due is at least it. */
    @Column(name = "floor", nullable = false)
    private BigDecimal floor = new BigDecimal("1.00");

    /** The starting terms (before every from-date): a claim is due by its date plus this many days. */
    @Column(name = "terms", nullable = false)
    private int terms = 14;

    /** Grade A's own terms in days; null when it uses the sheet's terms. */
    @Column(name = "terms_a")
    private Integer termsA;

    /** Grade B's own terms in days; null when it uses the sheet's terms. */
    @Column(name = "terms_b")
    private Integer termsB;

    /** Grade C's own terms in days; null when it uses the sheet's terms. */
    @Column(name = "terms_c")
    private Integer termsC;

    /** The starting late percent (before every from-date): an overdue claim's due gains it of its figure for every full 30 days overdue. */
    @Column(name = "late_pct", nullable = false)
    private BigDecimal latePct = new BigDecimal("0.00");

    /** The policy date: a claim dated before it rounds half up, on or after it half to even; null for the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** Period numbering from: a claim opened on or after it is numbered within its period; null for off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    /** Grace days: when today is changed, an open period whose to-date plus them is before it closes; null for off. */
    @Column(name = "grace_days")
    private Integer graceDays;

    /** Entry date: while set, a new claim with no date is dated it rather than the sheet's today; null for off. */
    @Column(name = "entry_date")
    private LocalDate entryDate;

    /** Archived: everything on the sheet stays visible but nothing on it may change. */
    @Column(name = "archived", nullable = false)
    private boolean archived;

    /** The last X-number given to a claim in no period while period numbering is on; 0 before any. */
    @Column(name = "last_unperiod_claim_number", nullable = false)
    private int lastUnperiodClaimNumber;

    /** The values settings carry from a date; before every from-date a setting has its column's value. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_setting", joinColumns = @JoinColumn(name = "sheet_id"))
    private List<DatedSetting> dated = new ArrayList<>();

    /** The permission matrix: for an action, the comma separated roles that may take it; an action with none keeps its standing rule. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_permission", joinColumns = @JoinColumn(name = "sheet_id"))
    @MapKeyColumn(name = "action")
    @Column(name = "roles", nullable = false)
    private Map<String, String> permissions = new HashMap<>();

    protected Sheet() {
    }

    /** The entry date as set; null when blank (off). */
    public LocalDate getEntryDate() {
        return entryDate;
    }

    public void setEntryDate(LocalDate entryDate) {
        this.entryDate = entryDate;
    }

    /** The date a new claim with no date of its own is given: the entry date while set, else the sheet's today. */
    public LocalDate defaultClaimDate() {
        return entryDate != null ? entryDate : today;
    }

    /** Whether a claim opened now is numbered within its period: the setting is a date on or before today. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** Give out the sheet's next number for a claim in no period: 1 for the first, then 2, and so on. */
    public int nextUnperiodClaimNumber() {
        return ++lastUnperiodClaimNumber;
    }

    /** Give out the sheet's next claim number: 1 for the first, then 2, and so on. */
    public int nextClaimNumber() {
        return ++lastClaimNumber;
    }

    /** The roles set for an action, comma separated; null when it keeps its standing rule. */
    public String getPermission(String action) {
        return permissions.get(action);
    }

    /** Set the roles that may take an action (null: the standing rule). */
    public void setPermission(String action, String roles) {
        if (roles == null) {
            permissions.remove(action);
        } else {
            permissions.put(action, roles);
        }
    }

    /** Whether a role may take an action: the roles set for it, else its standing rule. */
    public boolean permits(String action, String role) {
        String roles = permissions.getOrDefault(action, STANDING_PERMISSIONS.get(action));
        return Arrays.asList(roles.split(",")).contains(role);
    }
}
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /**
     * What the screen is told about a claim; the amount with two decimals, and the due fixed when it
     * was settled (null when not fixed, so its due is worked out from the current rate), and who
     * opened it (null until opened), and whether it is bound by its person's last statement, with the
     * figure it was bound to (null when unbound, or when it was n/a), and the number of the claim it
     * corrects (null unless it is a correction), and the date it is due by, fixed when it was added, and its status
     * log, oldest first, and the date it is deferred until (null when it was never deferred), and its proofs count,
     * and the number of the claim it was split from (null unless it was split off another), and the user whose open
     * editor locks it (null when none does), and the last day it was reminded (null when never), and its
     * external reference (null when it has none), and its tags, sorted, and every tag it has ever carried, sorted,
     * and the reason it was voided with (null when none), and its comments, oldest first, and the user who last edited it (null when never).
     */
    public record ClaimView(long id, long personId, String amount, LocalDate date, LocalDate dueBy, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects, List<LogLineView> log,
            LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy, boolean lateEntry, LocalDate remindedOn,
            String ref, List<String> tags, List<String> tagsUsed, String voidReason, List<CommentView> comments,
            String editedBy) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getDueBy(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getLog().stream().map(LogLineView::of).toList(), claim.getDeferredUntil(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(), claim.getRemindedOn(),
                    claim.getRef(), claim.getTags(), claim.getTagsUsed(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentView::of).toList(), claim.getEditedBy());
        }
    }

    /** A line of a claim's status log; the due with two decimals, or n/a. */
    public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {

        public static LogLineView of(ClaimLogLine line) {
            return new LogLineView(line.getStatus(), line.getBy(), line.getOn(),
                    line.getDue() == null ? "n/a" : line.getDue().toPlainString());
        }
    }

    /** A comment on a claim: by whom, on the sheet's today then, and its text. */
    public record CommentView(String by, LocalDate on, String text) {

        public static CommentView of(ClaimComment comment) {
            return new CommentView(comment.getBy(), comment.getOn(), comment.getText());
        }
    }

    /** A comment as typed on the claim; blank is refused. */
    public record CommentForm(@NotBlank @Size(max = 1000) String text) {
    }

    /**
     * A claim's values as entered on the form: the amount is required, with up to two decimals, and
     * below 0.00 only on a correction, which names the number of the claim it corrects; no date means
     * the sheet's today (or, on an edit, the claim's own); the note may be empty; a blank reference is
     * none (and on an edit, no reference at all keeps the claim's own); the tags are comma separated
     * (blank: none; on an edit, no tags at all keep the claim's own).
     */
    public record ClaimForm(
            @NotNull @Pattern(regexp = "-?\\d{1,12}(\\.\\d{1,2})?") String amount,
            LocalDate date,
            @Size(max = 500) String note,
            @Pattern(regexp = "[1-9]\\d{0,8}|\\S.{0,200}-[1-9]\\d{0,8}") String corrects,
            @Size(max = 200) String ref,
            @Size(max = 1000) String tags) {
    }

    /** Why a steward rejects a PENDING claim. */
    public record RejectForm(@NotBlank @Size(max = 200) String reason) {
    }

    private LocalDate dueFrom;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The sheet's number given to the claim when opened; null while DRAFT, and kept once VOID. */
    @Column(name = "claim_number")
    private String number;

    /** The due fixed when the claim was settled; null otherwise, or when the grade had no rate then. */
    @Column(name = "settled_due", precision = 14, scale = 2)
    private BigDecimal settledDue;

    /** The user who opened the claim; null until it is opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The user who last edited the claim; null when it was never edited. */
    @Column(name = "edited_by")
    private String editedBy;


    /** Whether the claim is bound by its person's last statement. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The due figure the claim was bound to by the statement; null when unbound, or when it was n/a. */
    @Column(name = "stated_due", precision = 14, scale = 2)
    private BigDecimal statedDue;

    /** The number of the claim this one corrects; null unless it is a correction. */
    @Column(name = "corrects")
    private String corrects;

    /** The claim's external reference; null when it has none. */
    @Column(name = "ref")
    private String ref;

    /** The reference as compared on the sheet (lower case); null when it has none. */
    @Column(name = "ref_key")
    private String refKey;

    /** The claim's tags, sorted and comma separated; null when it has none. */
    @Column(name = "tags")
    private String tags;

    /** Every tag the claim has ever carried, sorted and comma separated; null when none. */
    }

    /** Record the user who opened the claim. */
    public void openedBy(String user) {
        this.openedBy = user;
    }

    public String getEditedBy() {
        return editedBy;
    }

    /** Record the user who last edited the claim. */
    public void editedBy(String user) {
        this.editedBy = user;
    }

    /** Whether the user opened or last edited the claim, and so cannot settle or approve it. */
    public boolean isOpenedOrEditedBy(String user) {
        return user.equals(openedBy) || user.equals(editedBy);
    }

